SELECT setval('investory.ryczalt_period_id_seq', GREATEST((SELECT max(id) FROM ryczalt_period), 1), true);
SELECT setval('investory.ryczalt_native_month_input_id_seq', GREATEST((SELECT max(id) FROM ryczalt_native_month_input), 1), true);
